{ pkgs, config, ... }: {
  services.elasticsearch."es1" = {
    enable = true;
    plugins = [
      pkgs.elasticsearchPlugins.analysis-icu
    ];
  };
  settings.processes.test = {
    command = pkgs.writeShellApplication {
      runtimeInputs = [ pkgs.curl ];
      text = ''
        curl 127.0.0.1:9200/_cat/health 

        echo "Verify plugin installation"
        curl 127.0.0.1:9200/_cat/plugins | grep 'analysis-icu'
      '';
      name = "elasticsearch-test";
    };
    depends_on."es1".condition = "process_healthy";
  };
}

{ pkgs, config, ... }: {
  services.prometheus."pro1" = {
    enable = true;
    # scrape prometheus
    extraConfig = {
      scrape_configs = [
        {
          job_name = "prometheus";
          static_configs = [
            {
              targets = [ "localhost:9090" ];
            }
          ];
        }
      ];
    };
  };

  settings.processes.test =
    let
      cfg = config.services.prometheus."pro1";
    in
    {
      command = pkgs.writeShellApplication {
        runtimeInputs = [
          cfg.package
          pkgs.curl
          pkgs.gnugrep
        ];
        text = ''
          curl -sS ${cfg.listenAddress}:${builtins.toString cfg.port}/-/healthy
          curl -s -o /dev/null -w "%{http_code}" ${cfg.listenAddress}:${builtins.toString cfg.port}/metrics
        '';
        name = "prometheus-test";
      };
      depends_on."pro1".condition = "process_healthy";
    };
}

{ pkgs, config, ... }: {
  services.redis-cluster."c1".enable = true;

  settings.processes.test =
    let
      cfg = config.services.redis-cluster."c1";
    in
    {
      command = pkgs.writeShellApplication {
        runtimeInputs = [
          cfg.package
          pkgs.gnugrep
        ];
        text = ''
          redis-cli -p 30001 ping | grep -q "PONG"
          redis-cli -p 30002 ping | grep -q "PONG"
          redis-cli -p 30003 ping | grep -q "PONG"
          redis-cli -p 30004 ping | grep -q "PONG"
          redis-cli -p 30005 ping | grep -q "PONG"
          redis-cli -p 30006 ping | grep -q "PONG"
        '';
        name = "redis-cluster-test";
      };
      depends_on."c1-cluster-create".condition = "process_completed";
    };

}

{ pkgs, config, ... }: {
  services.redis."redis1".enable = true;

  services.redis."redis2" = { config, ... }: {
    enable = true;
    port = 0;
    unixSocket = "./redis.sock";
  };

  settings.processes.test =
    let
      cfg = config.services.redis."redis1";
    in
    {
      command = pkgs.writeShellApplication {
        runtimeInputs = [
          cfg.package
          pkgs.gnugrep
        ];
        text = ''
          echo  "Ping from redis1"
          redis-cli ping | grep "PONG"

          echo "Test connection to redis2 listening on Unix socket"
          echo "Ping from redis2"

          redis-cli -s ./data/redis2/redis.sock ping | grep "PONG"
        '';
        name = "redis-test";
      };
      depends_on."redis1".condition = "process_healthy";
      depends_on."redis2".condition = "process_healthy";
    };
}

{ pkgs, config, ... }:
let
  dashboardUid = "adnyzrfa5cqv4c";
  dashboardTitle = "Test dashboard";
  dashboards = pkgs.writeTextDir "dashboards/test_dashboard.json" ''
    {
      "annotations": {
        "list": [
          {
            "builtIn": 1,
            "datasource": {
              "type": "grafana",
              "uid": "-- Grafana --"
            },
            "enable": true,
            "hide": true,
            "iconColor": "rgba(0, 211, 255, 1)",
            "name": "Annotations & Alerts",
            "type": "dashboard"
          }
        ]
      },
      "editable": true,
      "fiscalYearStartMonth": 0,
      "graphTooltip": 0,
      "id": 3,
      "links": [],
      "panels": [],
      "schemaVersion": 39,
      "tags": [],
      "templating": {
        "list": []
      },
      "time": {
        "from": "now-6h",
        "to": "now"
      },
      "timepicker": {},
      "timezone": "browser",
      "title": "${dashboardTitle}",
      "uid": "${dashboardUid}",
      "version": 1,
      "weekStart": ""
    }
  '';
in
{
  services.grafana."gf1" = {
    enable = true;
    http_port = 3000;
    extraConf = {
      security.admin_user = "patato";
      security.admin_password = "potato";
    };
    providers = [
      {
        name = "Test dashboard provider";
        type = "file";
        options = {
          path = "${dashboards}/dashboards";
        };
      }
    ];
    declarativePlugins = with pkgs.grafanaPlugins; [ grafana-clickhouse-datasource ];
  };

  settings.processes.test =
    let
      cfg = config.services.grafana."gf1";
    in
    {
      # Tests based on: https://github.com/NixOS/nixpkgs/blob/master/nixos/tests/grafana/basic.nix
      command = pkgs.writeShellApplication {
        runtimeInputs = [
          cfg.package
          pkgs.gnugrep
          pkgs.curl
          pkgs.uutils-coreutils-noprefix
          pkgs.jq
        ];
        text = ''
          ADMIN=${cfg.extraConf.security.admin_user}
          PASSWORD=${cfg.extraConf.security.admin_password}
          ROOT_URL="${cfg.protocol}://${cfg.domain}:${builtins.toString cfg.http_port}";
          # The admin user can authenticate against the running service.
          curl -sSfN -u $ADMIN:$PASSWORD $ROOT_URL/api/org/users -i
          curl -sSfN -u $ADMIN:$PASSWORD $ROOT_URL/api/org/users | grep admin\@localhost
          # The dashboard provisioner was used to create a dashboard.
          curl -sSfN -u $ADMIN:$PASSWORD $ROOT_URL/api/dashboards/uid/${dashboardUid} -i
          curl -sSfN -u $ADMIN:$PASSWORD $ROOT_URL/api/dashboards/uid/${dashboardUid} | grep '"title":"${dashboardTitle}"'
          # Test for extra plugins added to grafana.
          curl -sSfN -u $ADMIN:$PASSWORD $ROOT_URL/api/plugins | jq '.[] | select(.id == "grafana-clickhouse-datasource") | .enabled' | grep "true"
        '';
        name = "grafana-test";
      };
      depends_on."gf1".condition = "process_healthy";
    };
}

{ pkgs, config, ... }:
{
  services.memcached."memcached1".enable = true;

  settings.processes.test =
    let
      cfg = config.services.memcached."memcached1";
    in
    {
      command = pkgs.writeShellApplication {
        runtimeInputs = [
          cfg.package
          pkgs.gnugrep
          pkgs.netcat
        ];
        text = ''
          echo -e "stats\nquit" | nc 127.0.0.1 11211 | grep "STAT version"
        '';
        name = "memcached-test";
      };
      depends_on."memcached1".condition = "process_healthy";
    };
}

{
  pkgs,
  config,
  name,
  ...
}:
{
  services.postgres."pg1" = {
    enable = true;
    initialScript.before = pkgs.writeText "init_before.sql" "CREATE USER bar;";
    initialScript.after = pkgs.writeText "init_after.sql" "CREATE DATABASE foo OWNER bar;";
  };
  services.postgres."pg2" = {
    enable = true;
    socketDir = "./test/new/socket/path";
    port = 5433;
    # INFO: pg1 creates $USER database while pg2 doesn't because `initialDatabases` is present
    initialDatabases = [
      {
        name = "sample-db";
        schemas = [ ./test.sql ];
      }
    ];
  };
  services.postgres."pg3" = {
    enable = true;
    socketDir = "./test/new/socket/path2";
    listen_addresses = "";
    initialDatabases = [
      {
        name = "test-db";
      }
    ];
  };

  # Tests if `pg4-init` fails due to `./bad_test.sql`
  services.postgres."pg4" = {
    enable = true;
    socketDir = "./test/new/socket/path3";
    listen_addresses = "";
    initialDatabases = [
      {
        name = "test-db";
        schemas = [ ./bad_test.sql ];
      }
    ];
  };
  # avoid both the processes trying to create `data` directory at the same time
  settings.processes."pg2-init".depends_on."pg1-init".condition = "process_completed_successfully";
  settings.processes."pg3-init".depends_on."pg2-init".condition = "process_completed_successfully";
  settings.processes."pg4-init".depends_on."pg3-init".condition = "process_completed_successfully";

  settings.processes.test =
    let
      cfg = config.services.postgres."pg1";
    in
    {
      command = pkgs.writeShellApplication {
        runtimeInputs = [
          cfg.package
          pkgs.gnugrep
          pkgs.curl
          pkgs.jq
        ];
        text = ''
          echo 'SELECT version();' | psql -h 127.0.0.1
          echo 'SHOW hba_file;' | psql -h 127.0.0.1 | ${pkgs.gawk}/bin/awk 'NR==3' | grep '^ /nix/store'

          # initialScript.before test
          echo "SELECT 1 FROM pg_roles WHERE rolname = 'bar';" | psql -h 127.0.0.1 | grep -q 1

          # initialScript.after test
          echo "SELECT 1 FROM pg_database WHERE datname = 'foo';" | psql -h 127.0.0.1 | grep -q 1

          # schemas test
          echo "SELECT * from users where user_name = 'test_user';" | psql -h 127.0.0.1 -p 5433 -d sample-db | grep -q test_user

          # listen_addresses test
          echo "SELECT 1 FROM pg_database where datname = 'test-db';" | psql -h "$(readlink -f ${config.services.postgres.pg3.socketDir})" -d postgres | grep -q 1

          # Test if `pg4-init` fails due to `bad_test.sql`
          #
          # The curl to process-compose server is documented in the swagger URL, http://localhost:8080, but since we are listening on unix socket here, you can use `socat` to temporarily pipe the port `8080` to the `pc-${name}.sock` (`socat TCP-LISTEN:8080,fork UNIX-CONNECT:/path/to/your/socket.sock

          # OpenAPI documentation from the swagger URL:
          # /process/logs/{name}/{endOffset}/{limit}
          curl --unix-socket pc-${name}.sock http://localhost/process/logs/pg4-init/0/30 | jq '.logs | contains(["ERROR:  syntax error at or near \"STABLE\""])' | grep "true"
        '';
        name = "postgres-test";
      };
      depends_on = {
        "pg1".condition = "process_healthy";
        "pg2".condition = "process_healthy";
        "pg3".condition = "process_healthy";
        "pg4-init".condition = "process_completed";
      };
    };
}

{
  imports = [
    ../services
    ./defaults.nix
  ];
}

# Default process-compose cli settings
{ pkgs, lib, ... }:
{
  cli = {
    # Disable the process-compose HTTP server
    options.no-server = lib.mkDefault true;
  };
}
